arguments.script:
const { spawnSync } = require('child_process');
const start = Date.now();
const result = spawnSync('cmd.exe', ['/c', 'npm run fetch-github-activity'], { encoding: 'utf8', env: process.env });
const out = (result.stdout || '').split(/\r?\n/).filter(Boolean);
const err = (result.stderr || '').split(/\r?\n/).filter(Boolean);
const interesting = [...out, ...err].filter(line => /github|activity|phase|endpoint|fallback|error|wrote|success|warning/i.test(line));
console.log(JSON.stringify({ command: 'npm run fetch-github-activity', exitCode: result.status, durationMs: Date.now()-start, interestingTail: interesting.slice(-30) }, null, 2));
process.exit(result.status ?? 1);

